package ama.governance;

import ama.contract.GovernanceContracts.ModelConfig;
import ama.contract.SpeechContracts.*;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.springframework.jdbc.core.JdbcTemplate;
import java.util.*;

/** Immutable task configuration; current consent and source validity remain revocable. */
public final class JdbcGovernanceRuntime {
 private static final ObjectMapper JSON=new ObjectMapper().configure(com.fasterxml.jackson.databind.SerializationFeature.ORDER_MAP_ENTRIES_BY_KEYS,true);
 private static final String ACTIVE_VOICE_SOURCE=" AND NOT EXISTS(SELECT 1 FROM meeting_voiceprint_application a JOIN meeting m ON m.id=a.meeting_id WHERE a.id=v.id AND (a.state<>'ACCEPTED' OR m.lifecycle<>'ACTIVE' OR m.governance_state<>'ACTIVE'))";
 private final JdbcTemplate j;
 public JdbcGovernanceRuntime(javax.sql.DataSource source){j=new JdbcTemplate(source);j.setQueryTimeout(5);}
 public record Snapshot(long revision,ModelConfig configuration,List<Map<String,Object>> corpus,String sha256){}
 public Snapshot preview(){var row=j.queryForMap("SELECT revision,CAST(config_json AS CHAR) configuration FROM governance_configuration ORDER BY revision DESC LIMIT 1");var corpus=j.queryForList(EFFECTIVE);if(corpus.size()>200)throw new IllegalStateException("Corpus capacity exceeded");for(var entry:corpus)for(String field:List.of("originalValue","suggestedValue"))entry.put(field,CorpusFeedbackService.redact((String)entry.get(field)));try{var config=JSON.readValue((String)row.get("configuration"),ModelConfig.class);return new Snapshot(((Number)row.get("revision")).longValue(),config,corpus,JdbcOperationsSupport.digest(write(config),write(corpus)));}catch(Exception bad){throw new IllegalStateException("Runtime configuration unavailable");}}
 public void freezeExact(String input,Snapshot snapshot){long current=j.queryForObject("SELECT revision FROM governance_configuration ORDER BY revision DESC LIMIT 1 FOR SHARE",Long.class);if(current!=snapshot.revision())throw new ama.contract.MeetingContracts.Conflict();j.update("INSERT INTO governance_runtime_snapshot(input_id,configuration_revision,configuration,corpus_json,snapshot_sha) VALUES (?,?,?,?,?)",input,snapshot.revision(),write(snapshot.configuration()),write(snapshot.corpus()),snapshot.sha256());}
 private static final String EFFECTIVE="SELECT f.id,CAST(f.revision AS CHAR) revisionToken,f.feedback_type feedbackType,f.original_value originalValue,f.suggested_value suggestedValue,b.adoption_version version FROM corpus_feedback_binding b JOIN feedback f ON f.id=b.feedback_id JOIN meeting m ON m.id=f.meeting_id JOIN enterprise_identity i ON i.enterprise_id=f.submitted_by WHERE f.state='ACCEPTED' AND f.feedback_type IS NOT NULL AND b.withdrawn=FALSE AND b.adoption_state='ADOPTED' AND m.lifecycle='ACTIVE' AND m.governance_state='ACTIVE' AND m.revision=b.source_revision AND m.owner_id=f.submitted_by AND i.status='ACTIVE' ORDER BY f.id LIMIT 201";
 public Snapshot freeze(String input){ama.contract.MinutesContracts.uuid(input);var saved=j.queryForList("SELECT * FROM governance_runtime_snapshot WHERE input_id=?",input);if(!saved.isEmpty())return snapshot(saved.getFirst());var config=j.queryForMap("SELECT revision,CAST(config_json AS CHAR) configuration FROM governance_configuration ORDER BY revision DESC LIMIT 1 FOR SHARE");var entries=j.queryForList(EFFECTIVE);if(entries.size()>200)throw new IllegalStateException("Effective corpus capacity exceeded");for(var entry:entries)for(String field:List.of("originalValue","suggestedValue"))entry.put(field,CorpusFeedbackService.redact((String)entry.get(field)));String corpus=write(entries),configuration=(String)config.get("configuration"),hash=JdbcOperationsSupport.digest(configuration,corpus);j.update("INSERT INTO governance_runtime_snapshot(input_id,configuration_revision,configuration,corpus_json,snapshot_sha) VALUES (?,?,?,?,?) ON DUPLICATE KEY UPDATE input_id=governance_runtime_snapshot.input_id",input,config.get("revision"),configuration,corpus,hash);return required(input);}
 public Snapshot required(String input){var rows=j.queryForList("SELECT * FROM governance_runtime_snapshot WHERE input_id=?",input);if(rows.size()!=1)throw new IllegalStateException("Governance task snapshot unavailable");return snapshot(rows.getFirst());}
 @SuppressWarnings("unchecked") private Snapshot snapshot(Map<String,Object> row){try{return new Snapshot(((Number)row.get("configuration_revision")).longValue(),JSON.readValue((String)row.get("configuration"),ModelConfig.class),JSON.readValue((String)row.get("corpus_json"),List.class),(String)row.get("snapshot_sha"));}catch(Exception bad){throw new IllegalStateException("Invalid task governance snapshot");}}
 public boolean corpusCurrent(String input){var saved=j.queryForList("SELECT * FROM governance_runtime_snapshot WHERE input_id=?",input);if(saved.isEmpty())return true;var frozen=snapshot(saved.getFirst()).corpus();if(frozen.isEmpty())return true;var active=new HashMap<String,Map<String,Object>>();for(var row:j.queryForList(EFFECTIVE))active.put((String)row.get("id"),row);return frozen.stream().allMatch(old->{var row=active.get(old.get("id"));return row!=null&&Objects.equals(old.get("revisionToken"),row.get("revisionToken"))&&Objects.equals(old.get("version"),row.get("version"));});}
 public List<String> entities(String input){var snapshot=required(input);if(!corpusCurrent(input))return List.of();return snapshot.corpus().stream().map(r->(String)r.get("suggestedValue")).filter(s->s!=null&&!s.isBlank()&&s.length()<=256&&s.indexOf('\n')<0&&s.indexOf('\r')<0).distinct().limit(128).toList();}
 public String activePrompt(){var value=j.queryForObject("SELECT CAST(config_json AS CHAR) FROM governance_configuration ORDER BY revision DESC LIMIT 1",String.class);try{return JSON.readValue(value,ModelConfig.class).promptVersion();}catch(Exception bad){throw new IllegalStateException("Active prompt unavailable");}}
 public void saveCandidates(String input,String file,long start,String speaker,List<VoiceprintService.Candidate> candidates){var snapshot=required(input);j.update("INSERT INTO governance_speaker_candidate(input_id,file_id,start_sample,speaker_id,candidates_json,configuration_revision) VALUES (?,?,?,?,?,?) ON DUPLICATE KEY UPDATE input_id=governance_speaker_candidate.input_id",input,file,start,speaker,write(candidates),snapshot.revision());}
 public void requireCandidate(String input,String voice,String subject,String sourceRevision,List<String> segments){
  ama.contract.MinutesContracts.uuid(voice);if(subject==null)throw new ama.contract.TranscriptContracts.Failure(409,"CORRECTION_STALE");var config=required(input).configuration();
  var valid=j.queryForList("SELECT v.id FROM governed_voiceprint v JOIN enterprise_identity i ON i.enterprise_id=v.subject_id WHERE v.id=? AND v.subject_id=? AND v.state='APPROVED' AND v.expires_at>UTC_TIMESTAMP(6) AND v.encrypted_embedding IS NOT NULL AND v.model_version=? AND i.status='ACTIVE'"+ACTIVE_VOICE_SOURCE+" FOR SHARE",String.class,voice,subject,config.modelVersion());
  if(config.voiceThreshold()==null||valid.isEmpty()||!candidateRows(input,false).stream().anyMatch(g->((List<?>)g.get("candidates")).stream().anyMatch(c->c instanceof Map<?,?> m&&voice.equals(m.get("voiceprintId"))&&subject.equals(m.get("subjectId")))))throw new ama.contract.TranscriptContracts.Failure(409,"CORRECTION_STALE");
  var groups=candidateRows(input,false);var positions=j.queryForList("SELECT segment_id,source_file_id,start_ms FROM transcript_segment WHERE revision_id=?",sourceRevision).stream().filter(s->segments.contains(s.get("segment_id"))).toList();
  if(positions.size()!=segments.size()||positions.stream().anyMatch(s->s.get("start_ms")==null||groups.stream().noneMatch(g->Objects.equals(g.get("fileId"),s.get("source_file_id"))&&Long.parseLong((String)g.get("startSample"))==((Number)s.get("start_ms")).longValue()*16&&((List<?>)g.get("candidates")).stream().anyMatch(c->c instanceof Map<?,?> m&&voice.equals(m.get("voiceprintId"))))))throw new ama.contract.TranscriptContracts.Failure(409,"CORRECTION_STALE");
 }
 public List<Map<String,Object>> candidateRows(String input){return candidateRows(input,true);}
 @SuppressWarnings("unchecked") private List<Map<String,Object>> candidateRows(String input,boolean external){
  var rows=j.queryForList("SELECT file_id fileId,CAST(start_sample AS CHAR) startSample,speaker_id speakerId,CAST(configuration_revision AS CHAR) configurationRevisionToken,CAST(candidates_json AS CHAR) candidates FROM governance_speaker_candidate WHERE input_id=? ORDER BY file_id,start_sample,speaker_id LIMIT 960",input);
  for(var group:rows){List<Map<String,Object>> candidates;try{candidates=JSON.readValue((String)group.get("candidates"),List.class);}catch(Exception bad){throw new IllegalStateException("Invalid speaker candidates");}var current=new ArrayList<Map<String,Object>>();for(var candidate:candidates){var people=j.queryForList("SELECT i.display_name displayName FROM governed_voiceprint v JOIN enterprise_identity i ON i.enterprise_id=v.subject_id WHERE v.id=? AND v.subject_id=? AND v.model_version=? AND v.state='APPROVED' AND v.encrypted_embedding IS NOT NULL AND v.expires_at>UTC_TIMESTAMP(6) AND i.status='ACTIVE'"+ACTIVE_VOICE_SOURCE,candidate.get("voiceprintId"),candidate.get("subjectId"),candidate.get("modelVersion"));if(people.size()==1&&(!external||GovernanceVoiceConsent.current(j,(String)candidate.get("voiceprintId")))){var item=new LinkedHashMap<>(candidate);item.put("displayName",people.getFirst().get("displayName"));current.add(item);}}group.put("candidates",current);}return rows;
 }
 public List<VoiceprintService.Candidate> match(String input,VoiceEmbedding embedding,EncryptedEmbeddingStore crypto){
  var config=required(input).configuration();if(config.voiceThreshold()==null||!config.modelVersion().equals(embedding.modelVersion()))return List.of();var rows=j.queryForList("SELECT v.* FROM governed_voiceprint v JOIN enterprise_identity i ON i.enterprise_id=v.subject_id WHERE v.state='APPROVED' AND v.expires_at>UTC_TIMESTAMP(6) AND v.encrypted_embedding IS NOT NULL AND v.model_version=? AND v.dimension=? AND i.status='ACTIVE'"+ACTIVE_VOICE_SOURCE+" ORDER BY v.id LIMIT 201",embedding.modelVersion(),embedding.dimension());if(rows.size()>200)throw new IllegalStateException("Voice candidate capacity exceeded");var entries=new ArrayList<VoiceprintService.Entry>();
  for(var row:rows){if(!GovernanceVoiceConsent.current(j,(String)row.get("id")))continue;String id=(String)row.get("id"),subject=(String)row.get("subject_id"),model=(String)row.get("model_version");int dimension=((Number)row.get("dimension")).intValue();Object raw=row.get("expires_at");var expires=raw instanceof java.sql.Timestamp t?t.toInstant():((java.time.LocalDateTime)raw).toInstant(java.time.ZoneOffset.UTC);entries.add(new VoiceprintService.Entry(id,subject,"APPROVED",true,expires,crypto.decrypt(id+":"+subject+":"+model+":"+dimension,model,dimension,(byte[])row.get("encrypted_embedding"))));}
  return new VoiceprintService().match(embedding,entries,config.voiceThreshold(),java.time.Instant.now());
 }
 private static String write(Object value){try{return JSON.writeValueAsString(value);}catch(Exception bad){throw new IllegalArgumentException("Invalid runtime governance data");}}
}
